using System;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "TamedRemorasOmenData", menuName = "Data/Battle/Omens System/Omen Data/Cellarius/TamedRemoras Omen Data")]
public class TamedRemorasOmenData : OmenData
{
	[Header("Tamed Remoras")]
	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[SerializeField]
	private AreaPurifyCorruptEffect areaPurifyCorruptEffect;

	[NonSerialized]
	private Action<int> omenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		omenAction = delegate(int effectAmount)
		{
			if (currentCorruptedAnimals.activeCorruptedAnimals.Count > 0)
			{
				Debug.Log("TAMED REMORAS");
				GameObject enemyWithLowestCorruption = currentCorruptedAnimals.GetEnemyWithLowestCorruption();
				if ((bool)enemyWithLowestCorruption)
				{
					Debug.Log(enemyWithLowestCorruption, enemyWithLowestCorruption);
					enemyWithLowestCorruption.GetComponent<UnitEffects>().AddEffect(areaPurifyCorruptEffect, effectAmount);
					omenInstance.EnqueueOmenFeedbackAndPlay();
				}
			}
		};
		ReferenceSingleton<CellariusOmensHandler>.Instance.TamedRemorasOmenAction = omenAction;
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<CellariusOmensHandler>.Instance.TamedRemorasOmenAction = null;
	}
}
